"""Node abstractions for the simulated network.

Mirrors the Mininet node hierarchy (Lantz et al., HotNets 2010): every element of
the emulated network is a ``Node``; hosts, switches and controllers specialise it.
"""


class Node:
    """Base class for anything that can terminate a link.

    A node owns a set of interfaces keyed by port number and carries an
    arbitrary parameter dictionary (the emulated equivalent of the options a
    real Mininet node would pass down to the network namespace).
    """

    #: Set on container-backed nodes (see :mod:`netsim.container`).
    is_container = False

    def __init__(self, name, ip=None, **params):
        self.name = name
        self.params = dict(params)
        self.intfs = {}
        self.ip = ip if ip is not None else params.get("ip")

    # -- interface management ------------------------------------------------
    def addIntf(self, intf, port=None):
        """Attach ``intf`` to this node, returning the port it landed on."""
        if port is None:
            port = self.newPort()
        self.intfs[port] = intf
        intf.node = self
        intf.port = port
        return port

    def newPort(self):
        """Return the next free port number (ports start at 0, as in Mininet)."""
        if not self.intfs:
            return 0
        return max(self.intfs.keys()) + 1

    def ports(self):
        return sorted(self.intfs.keys())

    def interfaces(self):
        return [self.intfs[p] for p in self.ports()]

    def connectionsTo(self, other):
        """Return [(local intf, remote intf)] for every link to ``other``."""
        result = []
        for intf in self.interfaces():
            link = intf.link
            if link is None:
                continue
            peer = link.peer_intf(intf)
            if peer is not None and peer.node is other:
                result.append((intf, peer))
        return result

    def links(self):
        seen = []
        for intf in self.interfaces():
            if intf.link is not None and intf.link not in seen:
                seen.append(intf.link)
        return seen

    def setIP(self, ip):
        self.ip = ip
        return ip

    def IP(self):
        return self.ip

    # -- lifecycle ----------------------------------------------------------
    def start(self, *args, **kwargs):
        """Hook for subclasses; the simulation has nothing to launch."""
        return None

    def stop(self, *args, **kwargs):
        return None

    def __repr__(self):
        return "<%s %s>" % (type(self).__name__, self.name)

    def __str__(self):
        return self.name


class Host(Node):
    """An emulated end host."""

    #: Simulated time (ms) needed to bring a namespace-based host up.
    HOST_STARTUP_MS = 10.0

    def __init__(self, name, ip=None, **params):
        Node.__init__(self, name, ip=ip, **params)

    @property
    def startup_time_ms(self):
        return self.HOST_STARTUP_MS


class Switch(Node):
    """An OpenFlow-capable switch.

    ``FORWARDING_OVERHEAD`` models the throughput cost of traversing one switch
    (2% per hop); the simulation engine applies it once per switch on a path.
    """

    FORWARDING_OVERHEAD = 0.02

    def __init__(self, name, dpid=None, **params):
        Node.__init__(self, name, **params)
        self.dpid = dpid if dpid is not None else self._default_dpid(name)
        self.controllers = []

    @staticmethod
    def _default_dpid(name):
        digits = "".join(ch for ch in name if ch.isdigit())
        return "%016x" % int(digits or 0)

    @property
    def forwarding_overhead(self):
        return self.FORWARDING_OVERHEAD

    @property
    def throughput_factor(self):
        """Fraction of offered load that survives one switch hop."""
        return 1.0 - self.FORWARDING_OVERHEAD

    def attach_controller(self, controller):
        if controller not in self.controllers:
            self.controllers.append(controller)
        return controller


class OVSSwitch(Switch):
    """Open vSwitch flavoured switch (the Mininet default)."""

    def __init__(self, name, dpid=None, failMode="secure", datapath="kernel",
                 **params):
        Switch.__init__(self, name, dpid=dpid, **params)
        self.failMode = failMode
        self.datapath = datapath


class Controller(Node):
    """An SDN controller reachable by the switches of the network."""

    def __init__(self, name, ip="127.0.0.1", port=6653, **params):
        Node.__init__(self, name, ip=ip, **params)
        self.port = port
        self.switches = []

    def register(self, switch):
        if switch not in self.switches:
            self.switches.append(switch)
        switch.attach_controller(self)
        return switch
"""Interfaces and links.

A :class:`Link` is the simulated counterpart of a veth pair: it creates an
:class:`Intf` on each side and records the traffic-control parameters
(bandwidth, delay, loss) the simulation engine uses for its measurements.
"""

DEFAULT_BW_MBPS = 1000.0


def parse_delay_ms(value):
    """Accept 2, 2.0, "2ms", "0.5 ms" or "2s" and return milliseconds."""
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().lower().replace(" ", "")
    for suffix, scale in (("us", 0.001), ("ms", 1.0), ("s", 1000.0)):
        if text.endswith(suffix):
            return float(text[: -len(suffix)]) * scale
    return float(text)


def parse_bw_mbps(value):
    """Accept 1000, 1000.0 or "1000mbit" and return Mbps (None stays None)."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().lower().replace(" ", "")
    for suffix, scale in (("gbit", 1000.0), ("mbit", 1.0), ("kbit", 0.001),
                          ("gbps", 1000.0), ("mbps", 1.0), ("kbps", 0.001)):
        if text.endswith(suffix):
            return float(text[: -len(suffix)]) * scale
    return float(text)


class Intf:
    """A network interface living on a node."""

    def __init__(self, name, node=None, port=None, link=None, ip=None,
                 **params):
        self.name = name
        self.node = node
        self.port = port
        self.link = link
        self.ip = ip
        self.params = dict(params)
        if node is not None:
            node.addIntf(self, port=port)

    def setIP(self, ip):
        self.ip = ip
        return ip

    def IP(self):
        return self.ip

    def __repr__(self):
        return "<Intf %s>" % self.name

    def __str__(self):
        return self.name


class Link:
    """A bidirectional link between two nodes."""

    def __init__(self, node1, node2, port1=None, port2=None,
                 intfName1=None, intfName2=None, cls=Intf,
                 bw=None, delay=0.0, loss=0.0, max_queue_size=None,
                 **params):
        self.node1 = node1
        self.node2 = node2
        self.bw = parse_bw_mbps(bw)
        self.delay = parse_delay_ms(delay)
        self.loss = float(loss or 0.0)
        self.max_queue_size = max_queue_size
        self.params = dict(params)

        if port1 is None:
            port1 = node1.newPort()
        if port2 is None:
            port2 = node2.newPort()
        if intfName1 is None:
            intfName1 = self.intfName(node1, port1)
        if intfName2 is None:
            intfName2 = self.intfName(node2, port2)

        self.intf1 = cls(intfName1, node=node1, port=port1, link=self)
        self.intf2 = cls(intfName2, node=node2, port=port2, link=self)
        self.port1 = self.intf1.port
        self.port2 = self.intf2.port

    @staticmethod
    def intfName(node, port):
        return "%s-eth%d" % (node.name, port)

    @property
    def loss_rate(self):
        """Loss as a probability in [0, 1] (``loss`` is a percentage)."""
        return max(0.0, min(100.0, self.loss)) / 100.0

    def bandwidth(self, default=DEFAULT_BW_MBPS):
        """Bandwidth in Mbps, falling back to ``default`` when unconstrained."""
        return default if self.bw is None else self.bw

    def peer_intf(self, intf):
        if intf is self.intf1:
            return self.intf2
        if intf is self.intf2:
            return self.intf1
        return None

    def endpoints(self):
        return (self.node1, self.node2)

    def connects(self, node1, node2):
        names = {self.node1.name, self.node2.name}
        return {getattr(node1, "name", node1),
                getattr(node2, "name", node2)} == names

    def intfList(self):
        return [self.intf1, self.intf2]

    def __repr__(self):
        return "<%s %s-%s>" % (type(self).__name__, self.intf1, self.intf2)

    def __str__(self):
        return "%s<->%s" % (self.intf1, self.intf2)


class TCLink(Link):
    """Link with explicit traffic-control parameters.

    ``bw`` is in Mbps, ``delay`` in milliseconds and ``loss`` in percent.
    """

    def __init__(self, node1, node2, port1=None, port2=None,
                 bw=None, delay=0.0, loss=0.0, max_queue_size=None,
                 use_htb=True, **params):
        Link.__init__(self, node1, node2, port1=port1, port2=port2,
                      bw=bw, delay=delay, loss=loss,
                      max_queue_size=max_queue_size, **params)
        self.use_htb = use_htb

    def config(self, bw=None, delay=None, loss=None):
        """Reconfigure the shaper after the link has been created."""
        if bw is not None:
            self.bw = parse_bw_mbps(bw)
        if delay is not None:
            self.delay = parse_delay_ms(delay)
        if loss is not None:
            self.loss = float(loss)
        return self

