"""Radio propagation models used by the wireless layer.

Mininet-WiFi (Fontes et al., CNSM 2015) drives link quality from a propagation
model; these functions provide the free-space and log-distance models plus the
RSSI/range helpers built on top of them.
"""

import math

#: Speed of light (m/s) as used by the Mininet-WiFi propagation models.
SPEED_OF_LIGHT = 3e8

DEFAULT_PATH_LOSS_EXP = 3.0
DEFAULT_REF_DISTANCE_M = 1.0


def friis_free_space_loss(freq_hz, distance_m):
    """Free-space path loss in dB: ``20*log10(4*pi*d*f/c)``."""
    if distance_m <= 0 or freq_hz <= 0:
        return 0.0
    return 20.0 * math.log10(
        (4.0 * math.pi * distance_m * freq_hz) / SPEED_OF_LIGHT)


def log_distance_path_loss(freq_hz, distance_m,
                           path_loss_exp=DEFAULT_PATH_LOSS_EXP,
                           ref_distance_m=DEFAULT_REF_DISTANCE_M):
    """Log-distance path loss: ``PL(d0) + 10*n*log10(d/d0)``.

    ``PL(d0)`` is the Friis loss at the reference distance.
    """
    if ref_distance_m <= 0:
        ref_distance_m = DEFAULT_REF_DISTANCE_M
    reference_loss = friis_free_space_loss(freq_hz, ref_distance_m)
    if distance_m <= ref_distance_m:
        return reference_loss
    return reference_loss + 10.0 * path_loss_exp * math.log10(
        distance_m / ref_distance_m)


def received_signal_strength(tx_power_dbm, freq_hz, distance_m,
                             path_loss_exp=DEFAULT_PATH_LOSS_EXP,
                             ref_distance_m=DEFAULT_REF_DISTANCE_M,
                             tx_gain_dbi=0.0, rx_gain_dbi=0.0):
    """RSSI in dBm: ``tx_power + gains - path_loss``."""
    path_loss = log_distance_path_loss(freq_hz, distance_m,
                                      path_loss_exp=path_loss_exp,
                                      ref_distance_m=ref_distance_m)
    return tx_power_dbm + tx_gain_dbi + rx_gain_dbi - path_loss


def max_range(tx_power_dbm, min_rssi_dbm, freq_hz,
              path_loss_exp=DEFAULT_PATH_LOSS_EXP,
              ref_distance_m=DEFAULT_REF_DISTANCE_M,
              tx_gain_dbi=0.0, rx_gain_dbi=0.0):
    """Distance (m) at which the RSSI drops to ``min_rssi_dbm``."""
    if ref_distance_m <= 0:
        ref_distance_m = DEFAULT_REF_DISTANCE_M
    if path_loss_exp <= 0:
        return float("inf")
    budget_db = (tx_power_dbm + tx_gain_dbi + rx_gain_dbi - min_rssi_dbm
                 - friis_free_space_loss(freq_hz, ref_distance_m))
    if budget_db <= 0:
        return ref_distance_m
    return ref_distance_m * 10.0 ** (budget_db / (10.0 * path_loss_exp))


def ghz_to_hz(freq_ghz):
    """Convenience conversion for the GHz-valued configuration entries."""
    return float(freq_ghz) * 1e9
"""WiFi stations: hosts that reach the network over a wireless link."""

from ..node import Host
from ..utils import distance_2d
from .propagation import ghz_to_hz, received_signal_strength


class Station(Host):
    """A wireless client with a position and (at most) one association."""

    def __init__(self, name, position=(0.0, 0.0), ip=None, **params):
        Host.__init__(self, name, ip=ip, **params)
        self.position = tuple(float(c) for c in position)
        self.associated_ap = None
        self.antenna_gain_dbi = float(params.get("antenna_gain_dbi", 0.0))
        self.association_history = []

    def set_position(self, position):
        """Move the station; associations are re-evaluated by the network."""
        self.position = tuple(float(c) for c in position)
        return self.position

    def distance_to(self, other):
        """Euclidean distance to another positioned node or an (x, y) tuple."""
        pos = getattr(other, "position", other)
        return distance_2d(self.position, pos)

    def rssi_from(self, ap):
        """Signal strength (dBm) this station sees from ``ap``."""
        return received_signal_strength(
            ap.tx_power_dbm,
            ghz_to_hz(ap.freq_ghz),
            self.distance_to(ap),
            path_loss_exp=ap.path_loss_exp,
            ref_distance_m=ap.ref_distance_m,
            rx_gain_dbi=self.antenna_gain_dbi,
            tx_gain_dbi=ap.antenna_gain_dbi,
        )

    @property
    def is_associated(self):
        return self.associated_ap is not None

    def associate(self, ap):
        """Attach to ``ap``, leaving any previous AP first."""
        if self.associated_ap is ap:
            return ap
        self.disassociate()
        self.associated_ap = ap
        if ap is not None:
            ap.associate(self)
        self.association_history.append(getattr(ap, "name", None))
        return ap

    def disassociate(self):
        previous = self.associated_ap
        if previous is not None:
            previous.disassociate(self)
        self.associated_ap = None
        return previous
"""Access points: switches with a radio."""

from ..node import Switch
from ..utils import distance_2d
from .propagation import (DEFAULT_PATH_LOSS_EXP, DEFAULT_REF_DISTANCE_M,
                          ghz_to_hz, max_range, received_signal_strength)


class AccessPoint(Switch):
    """A WiFi access point; a switch that stations can associate with."""

    def __init__(self, name, position=(0.0, 0.0), ssid=None, channel=1,
                 tx_power_dbm=20.0, freq_ghz=2.4,
                 path_loss_exp=DEFAULT_PATH_LOSS_EXP,
                 ref_distance_m=DEFAULT_REF_DISTANCE_M,
                 min_rssi_dbm=-80.0, mode="g", antenna_gain_dbi=0.0,
                 **params):
        Switch.__init__(self, name, **params)
        self.position = tuple(float(c) for c in position)
        self.ssid = ssid if ssid is not None else "%s-ssid" % name
        self.channel = channel
        self.tx_power_dbm = float(tx_power_dbm)
        self.freq_ghz = float(freq_ghz)
        self.path_loss_exp = float(path_loss_exp)
        self.ref_distance_m = float(ref_distance_m)
        self.min_rssi_dbm = float(min_rssi_dbm)
        self.mode = mode
        self.antenna_gain_dbi = float(antenna_gain_dbi)
        self.associated_stations = []

    # -- radio --------------------------------------------------------------
    @property
    def freq_hz(self):
        return ghz_to_hz(self.freq_ghz)

    def set_position(self, position):
        self.position = tuple(float(c) for c in position)
        return self.position

    def distance_to(self, other):
        pos = getattr(other, "position", other)
        return distance_2d(self.position, pos)

    def rssi_at(self, position, rx_gain_dbi=0.0):
        """RSSI (dBm) a receiver at ``position`` would measure."""
        return received_signal_strength(
            self.tx_power_dbm, self.freq_hz, self.distance_to(position),
            path_loss_exp=self.path_loss_exp,
            ref_distance_m=self.ref_distance_m,
            tx_gain_dbi=self.antenna_gain_dbi, rx_gain_dbi=rx_gain_dbi)

    @property
    def range_m(self):
        """Maximum distance at which the RSSI still exceeds ``min_rssi_dbm``."""
        return max_range(self.tx_power_dbm, self.min_rssi_dbm, self.freq_hz,
                         path_loss_exp=self.path_loss_exp,
                         ref_distance_m=self.ref_distance_m,
                         tx_gain_dbi=self.antenna_gain_dbi)

    def in_range(self, position, rx_gain_dbi=0.0):
        return self.rssi_at(position, rx_gain_dbi=rx_gain_dbi) >= \
            self.min_rssi_dbm

    # -- association --------------------------------------------------------
    def associate(self, station):
        if station not in self.associated_stations:
            self.associated_stations.append(station)
        return station

    def disassociate(self, station):
        if station in self.associated_stations:
            self.associated_stations.remove(station)
        return station

    def count_stations(self):
        return len(self.associated_stations)

    def __repr__(self):
        return "<AccessPoint %s ssid=%s pos=%s>" % (
            self.name, self.ssid, self.position)

