"""Mobility models producing reproducible position traces."""

import math

import numpy as np


class MobilityModel:
    """Base class: a seeded RNG plus a bounded movement area."""

    def __init__(self, area_width=200.0, area_height=200.0, seed=None):
        self.area_width = float(area_width)
        self.area_height = float(area_height)
        self.seed = seed
        self.rng = np.random.RandomState(seed)

    def reset(self, seed=None):
        """Restart the RNG so a trace can be reproduced exactly."""
        if seed is not None:
            self.seed = seed
        self.rng = np.random.RandomState(self.seed)
        return self

    def random_position(self):
        return (float(self.rng.uniform(0.0, self.area_width)),
                float(self.rng.uniform(0.0, self.area_height)))

    def clamp(self, position):
        x = min(max(position[0], 0.0), self.area_width)
        y = min(max(position[1], 0.0), self.area_height)
        return (float(x), float(y))

    def generate_trace(self, start_pos, num_steps):
        raise NotImplementedError


class RandomWaypointMobility(MobilityModel):
    """Random waypoint model.

    Each step the node advances toward its current waypoint at its current
    speed; on arrival (optionally after a pause) a new waypoint and speed are
    drawn.  All randomness comes from a ``numpy.random.RandomState`` so a given
    seed always yields the same trace.
    """

    def __init__(self, area_width=200.0, area_height=200.0, min_speed=1.0,
                 max_speed=5.0, pause_time=0, seed=None, **params):
        MobilityModel.__init__(self, area_width=area_width,
                               area_height=area_height, seed=seed)
        self.min_speed = float(min_speed)
        self.max_speed = float(max_speed)
        self.pause_time = int(pause_time)
        self.params = dict(params)

    def random_speed(self):
        if self.max_speed <= self.min_speed:
            return self.min_speed
        return float(self.rng.uniform(self.min_speed, self.max_speed))

    def generate_trace(self, start_pos=(0.0, 0.0), num_steps=100):
        """Return ``num_steps`` positions starting from ``start_pos``."""
        position = self.clamp(tuple(float(c) for c in start_pos))
        target = self.random_position()
        speed = self.random_speed()
        pause_left = 0
        trace = []
        for _ in range(int(num_steps)):
            if pause_left > 0:
                pause_left -= 1
                trace.append(position)
                continue
            dx = target[0] - position[0]
            dy = target[1] - position[1]
            distance = math.hypot(dx, dy)
            if distance <= speed or distance == 0.0:
                # Reached the waypoint: hop onto it and pick a new one.
                position = target
                target = self.random_position()
                speed = self.random_speed()
                pause_left = self.pause_time
            else:
                position = self.clamp((position[0] + dx / distance * speed,
                                       position[1] + dy / distance * speed))
            trace.append(position)
        return trace


class LinearMobility(MobilityModel):
    """Constant-velocity movement, useful for deterministic handover tests."""

    def __init__(self, area_width=200.0, area_height=200.0,
                 velocity=(1.0, 0.0), seed=None):
        MobilityModel.__init__(self, area_width=area_width,
                               area_height=area_height, seed=seed)
        self.velocity = (float(velocity[0]), float(velocity[1]))

    def generate_trace(self, start_pos=(0.0, 0.0), num_steps=100):
        position = self.clamp(tuple(float(c) for c in start_pos))
        trace = []
        for _ in range(int(num_steps)):
            position = self.clamp((position[0] + self.velocity[0],
                                   position[1] + self.velocity[1]))
            trace.append(position)
        return trace
"""Signal-aware wireless links."""

from ..link import TCLink

#: Simplified 802.11g rate table: (minimum RSSI in dBm, rate in Mbps).
RATE_TABLE = (
    (-50.0, 54.0),
    (-60.0, 48.0),
    (-65.0, 36.0),
    (-70.0, 24.0),
    (-75.0, 12.0),
    (-80.0, 6.0),
)


def bandwidth_for_rssi(rssi_dbm):
    """Map an RSSI to an 802.11g data rate (0 Mbps below sensitivity)."""
    if rssi_dbm is None:
        return 0.0
    for threshold, rate in RATE_TABLE:
        if rssi_dbm >= threshold:
            return rate
    return 0.0


class WirelessLink(TCLink):
    """A link whose bandwidth follows the measured signal strength.

    The RSSI is either given explicitly or derived from the station/AP
    positions; ``bw`` is then taken from the 802.11g rate table.
    """

    def __init__(self, node1, node2, rssi_dbm=None, delay=0.0, loss=0.0,
                 **params):
        if rssi_dbm is None:
            rssi_dbm = self._measure_rssi(node1, node2)
        self.rssi_dbm = rssi_dbm
        params.pop("bw", None)
        TCLink.__init__(self, node1, node2, bw=bandwidth_for_rssi(rssi_dbm),
                        delay=delay, loss=loss, **params)

    @staticmethod
    def _measure_rssi(node1, node2):
        """Compute RSSI for a station/AP pair, whichever way round it is."""
        for station, ap in ((node1, node2), (node2, node1)):
            if hasattr(station, "rssi_from") and hasattr(ap, "tx_power_dbm"):
                return station.rssi_from(ap)
            if hasattr(ap, "rssi_at") and hasattr(station, "position"):
                return ap.rssi_at(station.position)
        return None

    def update_rssi(self, rssi_dbm=None):
        """Recompute bandwidth after the station has moved."""
        if rssi_dbm is None:
            rssi_dbm = self._measure_rssi(self.node1, self.node2)
        self.rssi_dbm = rssi_dbm
        self.bw = bandwidth_for_rssi(rssi_dbm)
        return self.bw

    @property
    def bandwidth_mbps(self):
        return self.bandwidth(0.0)

