"""Container-backed hosts.

Containernet (Peuster et al., NetSoft 2018) replaces Mininet's namespace hosts
with Docker containers so that real network functions can be prototyped inside
an emulated topology.  A container brings its own image and resource limits and
takes noticeably longer to boot than a bare namespace, which is what
:class:`DockerHost` models here.
"""

from .node import Host

#: Docker's default CFS period (microseconds).
DEFAULT_CPU_PERIOD = 100000
#: Docker's default relative CPU weight.
DEFAULT_CPU_SHARES = 1024
#: Memory ceiling (MB) applied when the caller does not ask for one.
DEFAULT_MEM_LIMIT_MB = 512


class DockerHost(Host):
    """A host whose network namespace is provided by a container.

    ``cpu_shares`` is the relative CFS weight used when containers compete for
    the CPU; ``cpu_quota``/``cpu_period`` express a hard cap (the fraction of a
    core the container may use).
    """

    #: Simulated time (ms) to pull up a container: image start-up dominates.
    STARTUP_OVERHEAD_MS = 500.0
    #: Simulated time (ms) to bring up a plain namespace host, for comparison.
    HOST_STARTUP_MS = 10.0

    is_container = True

    def __init__(self, name, image="ubuntu:trusty", ip=None,
                 cpu_shares=DEFAULT_CPU_SHARES, cpu_quota=-1,
                 cpu_period=DEFAULT_CPU_PERIOD,
                 mem_limit_mb=DEFAULT_MEM_LIMIT_MB, dcmd=None, volumes=None,
                 port_bindings=None, environment=None, **params):
        Host.__init__(self, name, ip=ip, **params)
        self.image = image
        self.cpu_shares = int(cpu_shares)
        self.cpu_quota = int(cpu_quota)
        self.cpu_period = int(cpu_period)
        self.mem_limit_mb = float(mem_limit_mb)
        self.dcmd = dcmd
        self.volumes = list(volumes or [])
        self.port_bindings = dict(port_bindings or {})
        self.environment = dict(environment or {})
        self.running = False

    # -- resource limits ----------------------------------------------------
    @property
    def cpu_fraction(self):
        """Fraction of one CPU core the quota allows (1.0 when uncapped)."""
        if self.cpu_quota is None or self.cpu_quota <= 0:
            return 1.0
        if self.cpu_period <= 0:
            return 1.0
        return float(self.cpu_quota) / float(self.cpu_period)

    @property
    def mem_limit_bytes(self):
        return int(self.mem_limit_mb * 1024 * 1024)

    def update_resources(self, cpu_shares=None, cpu_quota=None,
                         cpu_period=None, mem_limit_mb=None):
        """Change the limits of a running container (``docker update``)."""
        if cpu_shares is not None:
            self.cpu_shares = int(cpu_shares)
        if cpu_quota is not None:
            self.cpu_quota = int(cpu_quota)
        if cpu_period is not None:
            self.cpu_period = int(cpu_period)
        if mem_limit_mb is not None:
            self.mem_limit_mb = float(mem_limit_mb)
        return self

    def cpu_share_of(self, total_shares):
        """This container's slice of the CPU given the total weight in play."""
        if not total_shares:
            return 0.0
        return float(self.cpu_shares) / float(total_shares)

    # -- lifecycle ----------------------------------------------------------
    @property
    def startup_time_ms(self):
        """Container boot time: the image start-up overhead."""
        return self.STARTUP_OVERHEAD_MS

    @property
    def startup_overhead_ratio(self):
        """How much slower this host boots than a namespace-only host."""
        if not self.HOST_STARTUP_MS:
            return 0.0
        return self.STARTUP_OVERHEAD_MS / self.HOST_STARTUP_MS

    def start(self, *args, **kwargs):
        self.running = True
        return self

    def stop(self, *args, **kwargs):
        self.running = False
        return self

    def __repr__(self):
        return "<DockerHost %s image=%s cpu_shares=%d mem=%.0fMB>" % (
            self.name, self.image, self.cpu_shares, self.mem_limit_mb)

