"""Service function chains.

A chain is an ordered list of virtual network functions between a client and a
server.  Traffic crosses ``len(vnfs) + 1`` links (client to the first VNF, one
link between each pair, and the last VNF to the server) and every VNF costs
both processing delay and a slice of the available throughput.
"""


class VNF:
    """One virtual network function in a chain."""

    def __init__(self, name, processing_delay_ms=0.0, overhead_pct=0.0,
                 image=None, cpu_shares=None, mem_limit_mb=None, **params):
        self.name = name
        self.processing_delay_ms = float(processing_delay_ms)
        self.overhead_pct = float(overhead_pct)
        self.image = image
        self.cpu_shares = cpu_shares
        self.mem_limit_mb = mem_limit_mb
        self.params = dict(params)

    @property
    def throughput_factor(self):
        """Fraction of the offered load this VNF passes on."""
        return 1.0 - self.overhead_pct / 100.0

    def __repr__(self):
        return "<VNF %s delay=%.2fms overhead=%.1f%%>" % (
            self.name, self.processing_delay_ms, self.overhead_pct)

    def __str__(self):
        return self.name


class ServiceFunctionChain:
    """An ordered chain of :class:`VNF` instances plus its link parameters."""

    def __init__(self, name="sfc", vnfs=None, link_bw=1000.0, link_delay=0.0,
                 link_loss=0.0, client="client", server="server"):
        self.name = name
        self.vnfs = list(vnfs or [])
        self.link_bw = float(link_bw)
        self.link_delay = float(link_delay)
        self.link_loss = float(link_loss)
        self.client = client
        self.server = server

    # -- construction -------------------------------------------------------
    def add_vnf(self, vnf, processing_delay_ms=0.0, overhead_pct=0.0,
                **params):
        """Append a VNF; ``vnf`` may be a :class:`VNF` or just a name."""
        if not isinstance(vnf, VNF):
            vnf = VNF(vnf, processing_delay_ms=processing_delay_ms,
                      overhead_pct=overhead_pct, **params)
        self.vnfs.append(vnf)
        return vnf

    @classmethod
    def uniform(cls, num_vnfs, processing_delay_ms=0.0, overhead_pct=0.0,
                prefix="vnf", **params):
        """Build a chain of identical VNFs (``vnf1``..``vnfN``)."""
        chain = cls(**params)
        for index in range(1, int(num_vnfs) + 1):
            chain.add_vnf("%s%d" % (prefix, index),
                          processing_delay_ms=processing_delay_ms,
                          overhead_pct=overhead_pct)
        return chain

    # -- queries ------------------------------------------------------------
    @property
    def num_vnfs(self):
        return len(self.vnfs)

    @property
    def num_links(self):
        """Links traversed end to end: one more than the number of VNFs."""
        return len(self.vnfs) + 1

    def node_names(self):
        """Chain endpoints in traversal order, client and server included."""
        return [self.client] + [v.name for v in self.vnfs] + [self.server]

    def throughput_factor(self):
        """Combined throughput factor of every VNF in the chain."""
        factor = 1.0
        for vnf in self.vnfs:
            factor *= vnf.throughput_factor
        return factor

    def processing_delay_ms(self):
        return sum(vnf.processing_delay_ms for vnf in self.vnfs)

    # -- performance model --------------------------------------------------
    def compute_throughput(self):
        """End-to-end throughput (Mbps): link rate cut by each VNF."""
        return self.link_bw * self.throughput_factor()

    def compute_latency(self):
        """End-to-end latency (ms): link delays plus VNF processing."""
        return self.num_links * self.link_delay + self.processing_delay_ms()

    def __len__(self):
        return len(self.vnfs)

    def __iter__(self):
        return iter(self.vnfs)

    def __repr__(self):
        return "<ServiceFunctionChain %s vnfs=%d links=%d>" % (
            self.name, len(self.vnfs), self.num_links)

