"""Containernet: a Mininet network that can also run container hosts.

Adds Docker-backed hosts (:class:`~netsim.container.DockerHost`) alongside the
regular namespace hosts, tracks their resource limits, and can deploy a
:class:`~netsim.sfc.ServiceFunctionChain` as a real chain of nodes in the
emulated topology.
"""

from .container import DockerHost
from .link import DEFAULT_BW_MBPS
from .net import Mininet
from .node import Host
from .sfc import ServiceFunctionChain, VNF
from .utils import jains_fairness_index


class Containernet(Mininet):
    """Mininet extended with container hosts and SFC deployment."""

    def __init__(self, topo=None, docker=DockerHost, **params):
        self.docker_hosts = []
        self.docker_cls = docker
        self.chains = {}
        Mininet.__init__(self, topo=topo, **params)

    # -- node creation ------------------------------------------------------
    def addDocker(self, name, image="ubuntu:trusty", cls=None, **params):
        """Add a container-backed host and return it."""
        host = self.addHost(name, cls=cls or self.docker_cls, image=image,
                            **params)
        self.docker_hosts.append(host)
        return host

    def removeDocker(self, name):
        """Detach a container host from the network."""
        host = self.get(name)
        if host in self.docker_hosts:
            self.docker_hosts.remove(host)
        if host in self.hosts:
            self.hosts.remove(host)
        self.nameToNode.pop(host.name, None)
        return host

    def regular_hosts(self):
        """Hosts that are not container-backed."""
        return [h for h in self.hosts if not getattr(h, "is_container", False)]

    def containers(self):
        return list(self.docker_hosts)

    # -- resource accounting ------------------------------------------------
    def cpu_shares(self):
        """CPU share weight of every container, in insertion order."""
        return [host.cpu_shares for host in self.docker_hosts]

    def total_cpu_shares(self):
        return sum(self.cpu_shares())

    def cpu_allocation(self):
        """Normalised CPU allocation per container name."""
        total = self.total_cpu_shares()
        return {host.name: host.cpu_share_of(total)
                for host in self.docker_hosts}

    def compute_resource_fairness(self, allocations=None):
        """Jain's fairness index of the container CPU share allocations."""
        if allocations is None:
            allocations = self.cpu_shares()
        return jains_fairness_index(list(allocations))

    def total_memory_mb(self):
        return sum(host.mem_limit_mb for host in self.docker_hosts)

    # -- start-up cost ------------------------------------------------------
    def startup_overhead_ratio(self):
        """Container boot time divided by namespace-host boot time."""
        container_ms = self.docker_cls.STARTUP_OVERHEAD_MS
        host_ms = getattr(self.host, "HOST_STARTUP_MS", None) or \
            self.docker_cls.HOST_STARTUP_MS
        if not host_ms:
            return 0.0
        return float(container_ms) / float(host_ms)

    def total_startup_time_ms(self):
        """Simulated time to boot every host of the network."""
        return sum(getattr(h, "startup_time_ms", Host.HOST_STARTUP_MS)
                   for h in self.hosts)

    # -- service function chains -------------------------------------------
    def addServiceFunctionChain(self, chain, image="ubuntu:trusty", **params):
        """Deploy ``chain`` as container hosts wired client->vnfs->server.

        Returns the list of created nodes in traversal order.  Each hop is a
        :class:`~netsim.container.DockerHost`; the client and server are plain
        hosts, giving ``chain.num_links`` links end to end.
        """
        if not isinstance(chain, ServiceFunctionChain):
            raise TypeError("expected a ServiceFunctionChain")
        nodes = [self.addHost(chain.client)]
        for vnf in chain.vnfs:
            nodes.append(self.addDocker(
                vnf.name, image=vnf.image or image,
                cpu_shares=vnf.cpu_shares if vnf.cpu_shares is not None
                else 1024,
                mem_limit_mb=vnf.mem_limit_mb if vnf.mem_limit_mb is not None
                else 512,
                **params))
        nodes.append(self.addHost(chain.server))
        for left, right in zip(nodes, nodes[1:]):
            self.addLink(left, right, bw=chain.link_bw, delay=chain.link_delay,
                         loss=chain.link_loss)
        self.chains[chain.name] = chain
        return nodes

    def chain_path(self, chain):
        """Node-name path through a deployed chain."""
        return self.path(chain.client, chain.server)

    def chain_throughput(self, chain):
        """Throughput (Mbps) measured over the deployed chain.

        The bottleneck link rate of the path, reduced by every switch hop and
        by each VNF's processing overhead.
        """
        path = self.chain_path(chain)
        if not path or len(path) < 2:
            return 0.0
        links = self.path_links(path)
        bw = min(l.bandwidth(DEFAULT_BW_MBPS) for l in links)
        for switch in self.path_switches(path):
            bw *= switch.throughput_factor
        return bw * chain.throughput_factor()

    def chain_latency(self, chain):
        """One-way latency (ms) over the deployed chain plus VNF processing."""
        path = self.chain_path(chain)
        if not path or len(path) < 2:
            return 0.0
        link_delay = sum(l.delay for l in self.path_links(path))
        return link_delay + chain.processing_delay_ms()

    def __repr__(self):
        return "<Containernet hosts=%d containers=%d switches=%d links=%d>" % (
            len(self.hosts), len(self.docker_hosts), len(self.switches),
            len(self.links))


__all__ = ["Containernet", "DockerHost", "ServiceFunctionChain", "VNF"]

