        evicted = 0
        for rule in self.rules:
            last = times.get(rule)
            if last is None:
                last = times.get(rule.match_key())
            if rule.is_expired(current_time, last):
                evicted += 1
                continue
            survivors.append(rule)
        self.rules = survivors
        self.evicted_count += evicted
        return evicted

    # -- queries ------------------------------------------------------------
    def size(self):
        return len(self.rules)

    def utilization(self):
        """Fraction of the table's capacity in use."""
        if not self.capacity:
            return 0.0
        return len(self.rules) / float(self.capacity)

    def stats(self):
        """``(rule, packet_count, byte_count)`` for every installed rule."""
        return [(rule, rule.packet_count, rule.byte_count)
                for rule in self.rules]

    def total_packets(self):
        return sum(rule.packet_count for rule in self.rules)

    def __len__(self):
        return len(self.rules)

    def __iter__(self):
        return iter(self.rules)

    def __repr__(self):
        return "<FlowTable %s rules=%d/%d>" % (
            self.switch_name, len(self.rules), self.capacity)


class SDNController:
    """Base controller: topology, path computation and rule installation."""

    #: Simulated cost (ms) of pushing one rule to a switch.
    rule_install_time_ms = 0.1

    def __init__(self, name="c0"):
        self.name = name
        self.flow_tables = {}
        self.switches = []
        self.hosts = []
        self.host_ips = {}
        self.adjacency = defaultdict(dict)
        self.ports = defaultdict(dict)
        self.paths = {}
        self.rules_installed = 0
        self.failed_links = []

    # -- topology -----------------------------------------------------------
    def add_switch(self, switch_name, capacity=4096):
        """Register a switch and give it an (empty) flow table."""
        name = getattr(switch_name, "name", switch_name)
        if name not in self.flow_tables:
            self.flow_tables[name] = FlowTable(name, capacity=capacity)
            self.switches.append(name)
        return self.flow_tables[name]

    def add_host(self, host_name, ip=None):
        """Register an end host (hosts have no flow table)."""
        name = getattr(host_name, "name", host_name)
        if name not in self.hosts:
            self.hosts.append(name)
        if ip is not None:
            self.host_ips[name] = ip
        return name

    def add_link(self, node1, node2, weight=1, port1=None, port2=None):
        """Add a bidirectional link to the topology graph."""
        name1 = getattr(node1, "name", node1)
        name2 = getattr(node2, "name", node2)
        self.adjacency[name1][name2] = float(weight)
        self.adjacency[name2][name1] = float(weight)
        if port1 is None:
            port1 = len(self.ports[name1])
        if port2 is None:
            port2 = len(self.ports[name2])
        self.ports[name1][name2] = port1
        self.ports[name2][name1] = port2
        return (name1, name2)

    def remove_link(self, node1, node2):
        """Remove a link, simulating a failure; True when one was removed."""
        name1 = getattr(node1, "name", node1)
        name2 = getattr(node2, "name", node2)
        if name2 not in self.adjacency.get(name1, {}):
            return False
        del self.adjacency[name1][name2]
        del self.adjacency[name2][name1]
        return True

    def has_link(self, node1, node2):
        return getattr(node2, "name", node2) in \
            self.adjacency.get(getattr(node1, "name", node1), {})

    def port_for(self, node, neighbor):
        """Output port on ``node`` facing ``neighbor``."""
        if neighbor is None:
            return None
        return self.ports.get(node, {}).get(neighbor)

    def topology_discovery(self, net):
        """Learn switches, hosts and links from a live network."""
        for switch in net.switches:
            self.add_switch(switch.name)
        for host in net.hosts:
            self.add_host(host.name, ip=host.ip)
        for link in net.links:
            self.add_link(link.node1.name, link.node2.name,
                          weight=1, port1=link.port1, port2=link.port2)
        return self

    @property
    def nodes(self):
        return list(self.adjacency.keys())

    # -- path computation ---------------------------------------------------
    def compute_path(self, src, dst):
        """Dijkstra shortest path; ``[]`` when the two nodes are disconnected."""
        src = getattr(src, "name", src)
        dst = getattr(dst, "name", dst)
        if src == dst:
            return [src]
        if src not in self.adjacency or dst not in self.adjacency:
            return []
        dist = {src: 0.0}
        previous = {src: None}
        visited = set()
        queue = [(0.0, src)]
        while queue:
            cost, node = heapq.heappop(queue)
            if node in visited:
                continue
            visited.add(node)
            if node == dst:
                break
            for neighbor, weight in sorted(self.adjacency[node].items()):
                if neighbor in visited:
                    continue
                new_cost = cost + weight
                if neighbor not in dist or new_cost < dist[neighbor]:
                    dist[neighbor] = new_cost
                    previous[neighbor] = node
                    heapq.heappush(queue, (new_cost, neighbor))
        if dst not in previous:
            return []
        path = []
        node = dst
        while node is not None:
            path.append(node)
            node = previous[node]
        path.reverse()
        return path

    def path_cost(self, path):
        return sum(self.adjacency[u][v] for u, v in zip(path, path[1:]))

    def compute_all_paths(self):
        """Shortest path for every ordered pair of hosts."""
        self.paths = {}
        for src in self.hosts:
            for dst in self.hosts:
                if src == dst:
                    continue
                path = self.compute_path(src, dst)
                if path:
                    self.paths[(src, dst)] = path
        return self.paths

    @staticmethod
    def path_uses_link(path, node1, node2):
        """True when ``path`` traverses the link between the two nodes."""
        for u, v in zip(path, path[1:]):
            if (u, v) == (node1, node2) or (u, v) == (node2, node1):
                return True
        return False

    # -- rule installation --------------------------------------------------
    def install_path_rules(self, path, src_ip, dst_ip, priority=100,
                           idle_timeout=0, hard_timeout=0, install_time=0.0):
        """Install a forwarding rule on every switch along ``path``.

        Returns the number of rules that were accepted.
        """
        installed = 0
        for index, node in enumerate(path or []):
            table = self.flow_tables.get(node)
            if table is None:
                continue
            next_hop = path[index + 1] if index + 1 < len(path) else None
            port = self.port_for(node, next_hop)
            rule = FlowRule({"src_ip": src_ip, "dst_ip": dst_ip},
                            [{"type": "output", "port": port}],
                            priority=priority, idle_timeout=idle_timeout,
                            hard_timeout=hard_timeout,
                            install_time=install_time)
            if table.install(rule):
                installed += 1
        self.rules_installed += installed
        return installed

    def remove_path_rules(self, path, src_ip, dst_ip):
        """Delete the rules a previous :meth:`install_path_rules` created."""
        removed = 0
        match = {"src_ip": src_ip, "dst_ip": dst_ip}
        for node in path or []:
            table = self.flow_tables.get(node)
            if table is not None and table.remove(match):
                removed += 1
        return removed

    def total_rules_installed(self):
        """Rules currently present across every flow table."""
        return sum(table.size() for table in self.flow_tables.values())

    def total_install_time(self):
        """Simulated time (ms) spent installing the rules that are in place."""
        return self.total_rules_installed() * self.rule_install_time_ms

    def ip_of(self, host):
        return self.host_ips.get(host, host)

    def host_for_ip(self, ip):
        """Reverse the host/IP mapping (used to resolve a packet's target)."""
        for host, host_ip in self.host_ips.items():
            if host_ip == ip:
                return host
        return None

    def evict_expired(self, current_time, last_matched_times=None):
        """Run timeout eviction on every switch; returns the total evicted."""
        return sum(table.evict_expired(current_time, last_matched_times)
                   for table in self.flow_tables.values())

    def clear_rules(self):
        for table in self.flow_tables.values():
            table.clear()
        return self

    # -- failure handling ---------------------------------------------------
    def handle_link_failure(self, node1, node2, priority=100):
        """Drop a link and reinstall the paths that were using it.

        Returns the number of rules that were reinstalled on the new paths.
        """
        name1 = getattr(node1, "name", node1)
        name2 = getattr(node2, "name", node2)
        affected = [(pair, path) for pair, path in self.paths.items()
                    if self.path_uses_link(path, name1, name2)]
        self.remove_link(name1, name2)
        self.failed_links.append((name1, name2))
        reinstalled = 0
        for (src, dst), old_path in affected:
            src_ip, dst_ip = self.ip_of(src), self.ip_of(dst)
            self.remove_path_rules(old_path, src_ip, dst_ip)
            new_path = self.compute_path(src, dst)
            if not new_path:
                self.paths.pop((src, dst), None)
                continue
            self.paths[(src, dst)] = new_path
            reinstalled += self.install_path_rules(new_path, src_ip, dst_ip,
                                                   priority=priority)
        return reinstalled

    def affected_flows(self, node1, node2):
        """Host pairs whose current path crosses the given link."""
        name1 = getattr(node1, "name", node1)
        name2 = getattr(node2, "name", node2)
        return [pair for pair, path in self.paths.items()
                if self.path_uses_link(path, name1, name2)]

    def __repr__(self):
        return "<%s %s switches=%d rules=%d>" % (
            type(self).__name__, self.name, len(self.flow_tables),
            self.total_rules_installed())


class ReactiveController(SDNController):
    """Installs rules only when a packet misses the flow tables."""

    #: Simulated controller time (ms) to service one packet-in.
    PACKET_IN_LATENCY_MS = 0.05

    def __init__(self, name="c0"):
        SDNController.__init__(self, name)
        self.packet_in_count = 0
        self.table_hits = 0
        self.unresolved_count = 0

    def handle_packet_in(self, switch_name, packet_headers):
        """Handle a table miss: compute the path and program it.

        Returns the path that was installed, or ``[]`` when the packet needed
        no new rules (the table already had a match) or could not be routed.
        """
        switch_name = getattr(switch_name, "name", switch_name)
        self.packet_in_count += 1
        headers = packet_headers or {}
        table = self.flow_tables.get(switch_name)
        if table is not None and table.lookup(headers) is not None:
            self.table_hits += 1
            return []

        src_ip = headers.get("src_ip")
        dst_ip = headers.get("dst_ip")
        src = self.host_for_ip(src_ip) or switch_name
        dst = self.host_for_ip(dst_ip)
        if dst is None:
            self.unresolved_count += 1
            return []
        path = self.compute_path(src, dst)
        if not path:
            self.unresolved_count += 1
            return []
        self.paths[(src, dst)] = path
        self.install_path_rules(path, src_ip, dst_ip,
                               priority=headers.get("priority", 100),
                               idle_timeout=headers.get("idle_timeout", 0),
                               hard_timeout=headers.get("hard_timeout", 0))
        return path

    # -- control-plane load -------------------------------------------------
    def processing_time_ms(self, num_packets=None):
        """Simulated time (ms) spent servicing packet-ins."""
        if num_packets is None:
            num_packets = self.packet_in_count
        return num_packets * self.PACKET_IN_LATENCY_MS

    def packet_in_throughput(self, num_packets=None):
        """Packet-in events the controller can service per simulated second."""
        elapsed_ms = self.processing_time_ms(num_packets)
        if elapsed_ms <= 0:
            return 0.0
        if num_packets is None:
            num_packets = self.packet_in_count
        return num_packets / (elapsed_ms / 1000.0)


class ProactiveController(SDNController):
    """Installs the rules for every host pair before any traffic flows."""

    def __init__(self, name="c0"):
        SDNController.__init__(self, name)
        self.rule_install_time_ms = SDNController.rule_install_time_ms

    def install_all_rules(self, hosts_with_ips=None, priority=100,
                          idle_timeout=0, hard_timeout=0, install_time=0.0):
        """Program every src/dst host pair; returns the rules installed."""
        if hosts_with_ips is None:
            hosts_with_ips = dict(self.host_ips)
        elif isinstance(hosts_with_ips, dict):
            hosts_with_ips = dict(hosts_with_ips)
        else:
            hosts_with_ips = dict(hosts_with_ips)
        for host, ip in hosts_with_ips.items():
            self.add_host(host, ip=ip)

        installed = 0
        for src, src_ip in hosts_with_ips.items():
            for dst, dst_ip in hosts_with_ips.items():
                if src == dst:
                    continue
                path = self.compute_path(src, dst)
                if not path:
                    continue
                self.paths[(src, dst)] = path
                installed += self.install_path_rules(
                    path, src_ip, dst_ip, priority=priority,
                    idle_timeout=idle_timeout, hard_timeout=hard_timeout,
                    install_time=install_time)
        return installed


